-- cups-web —— PostgreSQL 建表语句
--
-- 手动建表：psql -U <user> -d <db> -f schema.sql
--
-- ⚠️ 这是【唯一的事实来源】：Go 侧用 //go:embed 读同一个文件在启动时执行
--    （全部是 IF NOT EXISTS，可重复执行）。所以不要手改数据库结构后不回来
--    改这里 —— 那样代码和线上库会分叉，而分叉在开发机上永远看不出来。
--
-- ── 列类型与 SQLite 版的对应关系 ──────────────────────────────────
--   INTEGER PRIMARY KEY AUTOINCREMENT → BIGINT GENERATED BY DEFAULT AS IDENTITY
--   0/1 的布尔列                      → boolean
--   金额（分）、计数                   → BIGINT
--   RFC3339 文本时间                   → TEXT（见下）
--
-- ── 为什么时间用 TEXT 而不是 timestamptz ──────────────────────────
-- 技术上 timestamptz 是更"正统"的类型。但换它的代价是：Go 侧 25 个时间字段
-- 要从 string 改成 time.Time，连带 23 处 nowUTC()、39 处 time.RFC3339、
-- 7 处 time.Parse、34 条 SQL 时间比较 —— 约 120 处改动。
--
-- 而 TEXT 存 RFC3339 UTC 不是将就：**UTC 的字典序等于时间序**，所以
-- 排序和 `created_at < ?` 的比较结果全部正确，现有代码一行都不用动。
-- 索引照常生效（B-tree 对 text 一样用）。
--
-- 另一个理由是本仓库的教训：AGENTS.md 记着「timestamp 必须用东八区，
-- 用本地时间会差 8 小时 —— 这个 bug 在开发机上永远复现不了」。
-- 把时间在 Go 里当字符串传，恰恰消灭了这一整类错误。
--
-- ⚠️ 因此 `expires_at <> ''` 这类判空写法在 PG 下【依然正确】（空串还是空串），
--    不要顺手改成 IS NOT NULL —— 那是在为 NULL 语义写代码，而这里没有 NULL。
--
-- 以后真要用 PG 的日期函数/范围索引，再做一次迁移，把 TEXT 转成 timestamptz
-- 并同步改 Go 侧那 120 处。那是一次独立的、有明确收益的工作。

-- ── 用户 ────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS users (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username      TEXT    NOT NULL UNIQUE,
    password_hash TEXT    NOT NULL,
    role          TEXT    NOT NULL,          -- 'admin' / 'user'
    protected     BOOLEAN NOT NULL DEFAULT false,
    contact_name  TEXT,
    phone         TEXT,
    email         TEXT,
    balance_cents BIGINT  NOT NULL DEFAULT 0, -- 余额只能经 store.ApplyWalletDelta 变动
    created_at    TEXT    NOT NULL,           -- RFC3339 UTC
    updated_at    TEXT    NOT NULL
);

-- 支付宝授权登录：把「支付宝用户」关联到 users。
--
-- ⚠️ 这是本仓库第一个 ALTER TABLE。新库由上面的 CREATE 建出基础列，存量库靠
-- 这一句补上；ADD COLUMN IF NOT EXISTS 本身可重复执行，而 applySchema 每次启动
-- 都会把整份文件重跑一遍，所以幂等是硬要求（见 docs/conventions.md）。
-- 刻意【不】把这一列写进上面的 CREATE：那样就有两处定义，迟早漂移。
--
-- '' 表示「不是支付宝账号」——本仓库空值一律用 '' 而不是 NULL（见文件顶部约定）。
-- 存的是 open_id（128 字符）而不是 user_id：官方说 user_id 未来会逐步回收，
-- 新商户应当用 open_id（需在「应用-开发配置-openid 配置管理」里启用）。
ALTER TABLE users ADD COLUMN IF NOT EXISTS alipay_open_id TEXT NOT NULL DEFAULT '';

-- 一个支付宝账号只对应一个用户。'' 不参与唯一性，所以是【部分】唯一索引 ——
-- 普通账号（大量 ''）互不冲突，只有真实的 open_id 被约束。
CREATE UNIQUE INDEX IF NOT EXISTS idx_users_alipay_open_id
    ON users(alipay_open_id) WHERE alipay_open_id <> '';

-- NFC 工牌号（刷卡取件用）。'' = 没绑卡。
--
-- ⚠️ 存的是【归一后】的形式（store.NormalizeCardNo）：去掉空白与
-- `:` `-` `_` 这类分隔符、转大写。读与写【两侧都过同一个函数】，所以
-- 这个归一是对称的、不会把两张不同的卡弄成一张；而它解决的是两件
-- 几乎必然发生的事：
--   ① PC/SC 读卡器（ACR122U 等）吐十六进制 UID，管理员把终端上看到的
--      `04A23B1C` 抄进管理界面时，大小写几乎一定会有抄错的时候；
--   ② 同一个 UID 各家写成 `04:A2:3B:1C` / `04-A2-3B-1C` / `04A23B1C` 都有。
--
-- 🚫 归一【不】去前导零、不删数字 —— 那会改变卡的身份。
-- 🚫 它也救不了「两台不同型号读卡器读出不同 UID」（Wiegand 号 vs 卡面号、
--    字节序不同）：那是物理层差异，只能靠统一读卡器型号。
--    换型号就要重新绑卡。
--
-- 换卡 = 重新绑（覆盖这一列）。一个人要多张卡同时生效的话，这一列不够，
-- 得升级成 user_cards(user_id, card_no UNIQUE) 的多行表 —— 现在不做，
-- 但升级路径写进了 docs/pull-printing.md。
ALTER TABLE users ADD COLUMN IF NOT EXISTS card_no TEXT NOT NULL DEFAULT '';

-- 一张卡只能绑一个人。与 alipay_open_id 同样是【部分】唯一索引：
-- 未绑卡的账号（大量 ''）互不冲突。
CREATE UNIQUE INDEX IF NOT EXISTS idx_users_card_no
    ON users(card_no) WHERE card_no <> '';

-- ── 取件终端（刷卡取件）──────────────────────────────────────────────
-- 打印机旁那台树莓派的身份。token 是【这台终端】的凭据，不是账号凭据。
--
-- ⚠️ 它是本系统唯一的【无会话写入口】（取件端没有浏览器、没有登录），
-- 所以 kiosk_handlers.go 里必须配速率限制 + 审计日志。安全边界：
-- 拿到 token 最多能冒充一台取件终端，而释放仍需一张能刷出卡号的实体卡，
-- 纸也只会从这台物理打印机出来 —— 门槛实际等于物理接触那台读卡器。
--
-- ── 工牌绑定窗口（「在系统里点绑卡 → 到终端刷卡」）──────────────────
-- 管理员点「绑卡」时开一个短命窗口；在它有效期内，终端刷到的卡会被绑到
-- 目标用户，而不是去取件。
--
-- ⚠️ 为什么需要它：读卡器挂在打印机旁的终端上，**浏览器访问不到它**。
-- 所以「在哪点按钮」和「在哪刷卡」天生是两个地方，中间必须由服务端记住
-- 「现在这次刷卡是给谁绑的」。没有这张表就只能让管理员到终端读出 UID、
-- 再抄进管理界面（`kiosk.py --read`，那条路仍然保留着）。
--
-- ⚠️ 为什么是表而不是进程内变量：终端与浏览器是两个独立请求，
-- 而且这个部署一旦多实例，进程内的东西就互相看不见。
CREATE TABLE IF NOT EXISTS card_bind_sessions (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id    BIGINT  NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_by TEXT    NOT NULL DEFAULT '',   -- 哪个管理员开的（审计）
    created_at TEXT    NOT NULL,
    expires_at TEXT    NOT NULL,
    card_no    TEXT    NOT NULL DEFAULT '',   -- 绑定成功后回填
    done       BOOLEAN NOT NULL DEFAULT FALSE,
    -- error 记「这次刷卡为什么没绑上」（比如卡已绑给别人）。
    -- ⚠️ 它【不】关闭窗口：管理员可以直接换一张卡再刷，
    -- 而不必回到电脑前重新点一次。
    error      TEXT    NOT NULL DEFAULT ''
);

-- 🚨 全局单飞：同一时刻只允许存在一个未完成的绑定窗口。
--
-- 索引列是 done、谓词是 NOT done，所以索引里只会有 done=false 这一种值 ——
-- 唯一约束于是退化成「这种行最多一条」。少了它，两个窗口同时开着的时候，
-- 一次刷卡究竟绑给谁是不确定的。
CREATE UNIQUE INDEX IF NOT EXISTS idx_card_bind_sessions_active
    ON card_bind_sessions(done) WHERE NOT done;

-- printer_uri 是硬约束：任务在哪台提交就只能在哪台取。提交时选的这台
-- 若没有启用的终端，任务就是取不出来的黑洞 —— 所以提交页只列出有终端的
-- 打印机（/api/printers 会带 hasKiosk），后端再校验一次。
--
-- ⚠️ printer_uri = '' 表示这是一台【仅用于绑卡】的终端，不是「忘了填」：
-- 绑卡只需要读一次卡的 UID，而 UID 是芯片固化的 —— 读卡器插在哪台机器上
-- 读出来都是同一个值（这正是 PC/SC 相比键盘模拟读卡器的好处）。
-- 所以管理员完全可以把读卡器插在自己电脑上、配一台只绑卡的终端，
-- 不必为了绑一张卡走到打印机那边去。
-- 这种终端在没有等待中的绑定窗口时会明确回一句「请先在管理界面点
-- 开始等待刷卡」，而不是含糊的「没有待取件任务」。
CREATE TABLE IF NOT EXISTS kiosk_terminals (
    token        TEXT    PRIMARY KEY,           -- randomToken()，不透明、不可枚举
    name         TEXT    NOT NULL DEFAULT '',   -- 展示名，如「3楼东侧」
    printer_uri  TEXT    NOT NULL,              -- '' = 仅用于绑卡，不负责取件
    enabled      BOOLEAN NOT NULL DEFAULT true,
    created_at   TEXT    NOT NULL,              -- RFC3339 UTC
    last_seen_at TEXT    NOT NULL DEFAULT ''    -- '' = 从未上线
);

-- 支付宝授权登录的【短命状态】：浏览器发起授权后，靠它把结果领回去。
--
-- 为什么要它，而不是把 state 放在签名 cookie 里：
-- 授权与兑换【必然发生在支付宝的 webview】，而发起可能发生在普通浏览器 ——
-- 浏览器和 webview 是【两个 cookie 罐】，cookie 过不去。所以状态只能放服务端。
-- （这是真机测出来的，不是设计偏好。）
--
-- 流程：start 时插入一行（user_id=0）→ webview 里兑换成功后把 user_id 写进来
-- → 浏览器轮询到 user_id 非 0，就给自己签发会话并把这一行删掉。
--
-- from_browser 记录"发起方是普通浏览器"，也就是"会有人来轮询"。
-- 支付宝扫一扫直接进来的那种没有轮询方，它在 webview 里就地登录。
CREATE TABLE IF NOT EXISTS alipay_login_states (
    state        TEXT    PRIMARY KEY,
    user_id      BIGINT  NOT NULL DEFAULT 0,     -- 0 = 还没完成
    from_browser BOOLEAN NOT NULL DEFAULT false,
    created_at   TEXT    NOT NULL                -- RFC3339 UTC
);

-- ── 设置（KV）──────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS settings (
    key   TEXT PRIMARY KEY,
    value TEXT NOT NULL
);

-- ── 定时打印 ────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS scheduled_prints (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id          BIGINT  NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name             TEXT    NOT NULL DEFAULT '',
    printer_uri      TEXT    NOT NULL,
    filename         TEXT    NOT NULL,
    stored_path      TEXT    NOT NULL,
    is_duplex        BOOLEAN NOT NULL DEFAULT false,
    is_color         BOOLEAN NOT NULL DEFAULT true,
    copies           BIGINT  NOT NULL DEFAULT 1,
    orientation      TEXT    NOT NULL DEFAULT 'portrait',
    paper_size       TEXT    NOT NULL DEFAULT 'A4',
    paper_type       TEXT    NOT NULL DEFAULT 'plain',
    media_source     TEXT    NOT NULL DEFAULT 'auto',
    print_scaling    TEXT    NOT NULL DEFAULT 'fit',
    page_range       TEXT    NOT NULL DEFAULT '',
    page_set         TEXT    NOT NULL DEFAULT 'all',
    mirror           BOOLEAN NOT NULL DEFAULT false,
    watermark_text   TEXT    NOT NULL DEFAULT '',
    number_up        BIGINT  NOT NULL DEFAULT 1,
    number_up_layout TEXT    NOT NULL DEFAULT 'lrtb',
    page_border      TEXT    NOT NULL DEFAULT 'none',
    schedule_type    TEXT    NOT NULL DEFAULT 'once',
    schedule_time    TEXT    NOT NULL DEFAULT '09:00',
    schedule_weekday BIGINT  NOT NULL DEFAULT 0,
    schedule_day     BIGINT  NOT NULL DEFAULT 1,
    run_at           TEXT    NOT NULL DEFAULT '',   -- '' = 未设置
    next_run_at      TEXT    NOT NULL,
    last_run_at      TEXT    NOT NULL DEFAULT '',   -- '' = 未运行过
    last_status      TEXT    NOT NULL DEFAULT '',
    last_error       TEXT    NOT NULL DEFAULT '',
    enabled          BOOLEAN NOT NULL DEFAULT true,
    created_at       TEXT    NOT NULL,
    updated_at       TEXT    NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_scheduled_prints_next
    ON scheduled_prints(enabled, next_run_at);

-- ── 打印记录 ────────────────────────────────────────────────────────
-- 参数列是「完整快照」，供「重新打印」精确预填第一次的每一项设置。
CREATE TABLE IF NOT EXISTS print_jobs (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id          BIGINT  NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    printer_uri      TEXT    NOT NULL,
    filename         TEXT    NOT NULL,
    stored_path      TEXT    NOT NULL,
    pages            BIGINT  NOT NULL,
    job_id           TEXT,
    status           TEXT    NOT NULL,       -- queued / printed / failed / cancelled
    is_duplex        BOOLEAN NOT NULL DEFAULT false,
    is_color         BOOLEAN NOT NULL DEFAULT true,
    copies           BIGINT  NOT NULL DEFAULT 1,
    orientation      TEXT    NOT NULL DEFAULT 'portrait',
    paper_size       TEXT    NOT NULL DEFAULT 'A4',
    paper_type       TEXT    NOT NULL DEFAULT 'plain',
    media_source     TEXT    NOT NULL DEFAULT 'auto',
    print_scaling    TEXT    NOT NULL DEFAULT 'fit',
    page_range       TEXT    NOT NULL DEFAULT '',
    page_set         TEXT    NOT NULL DEFAULT 'all',
    mirror           BOOLEAN NOT NULL DEFAULT false,
    watermark_text   TEXT    NOT NULL DEFAULT '',
    number_up        BIGINT  NOT NULL DEFAULT 1,
    number_up_layout TEXT    NOT NULL DEFAULT 'lrtb',
    page_border      TEXT    NOT NULL DEFAULT 'none',
    created_at       TEXT    NOT NULL
);
-- ⚠️ 老库上这张表【一根索引都没有】。下面两条是补的：
--   created_at —— 管理端列表要 ORDER BY created_at DESC（无索引=全表排序），
--                 维护任务每小时那条 DELETE ... WHERE created_at < ? 同理。
--   user_id    —— 用户查自己的打印记录。
CREATE INDEX IF NOT EXISTS idx_print_jobs_created ON print_jobs(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_print_jobs_user_created ON print_jobs(user_id, created_at DESC);

-- ── 单价表 ──────────────────────────────────────────────────────────
-- 全量替换式配置（PUT 时 DELETE + INSERT），量级几十行，用唯一索引保证维度组合唯一。
CREATE TABLE IF NOT EXISTS price_rules (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    is_color         BOOLEAN NOT NULL DEFAULT false,
    paper_size       TEXT    NOT NULL,
    paper_type       TEXT    NOT NULL,
    unit_price_cents BIGINT  NOT NULL DEFAULT 0,
    updated_at       TEXT    NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_price_rules_dim
    ON price_rules(is_color, paper_size, paper_type);

-- ── 打印订单 ────────────────────────────────────────────────────────
-- 订单自带完整参数快照，【不引用 print_jobs】—— 管理员关掉 save_history 时
-- 那张表根本不写记录，而账目不能因此消失。列里存的是「最终发给 IPP 的值」
-- （缩放已解析、even-reverse 已消化、手动双面已强制单面），支付后直接重放。
CREATE TABLE IF NOT EXISTS print_orders (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id              BIGINT  NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    source               TEXT    NOT NULL DEFAULT 'web',
    reprint_of           BIGINT  NOT NULL DEFAULT 0,
    scheduled_id         BIGINT  NOT NULL DEFAULT 0,
    batch_id             TEXT    NOT NULL DEFAULT '',

    printer_uri          TEXT    NOT NULL,
    filename             TEXT    NOT NULL,
    stored_path          TEXT    NOT NULL,
    print_path           TEXT    NOT NULL,
    print_mime           TEXT    NOT NULL DEFAULT '',

    pages                BIGINT  NOT NULL DEFAULT 0,
    billed_pages         BIGINT  NOT NULL DEFAULT 0,

    is_duplex            BOOLEAN NOT NULL DEFAULT false,
    is_color             BOOLEAN NOT NULL DEFAULT true,
    copies               BIGINT  NOT NULL DEFAULT 1,
    orientation          TEXT    NOT NULL DEFAULT 'portrait',
    paper_size           TEXT    NOT NULL DEFAULT 'A4',
    paper_type           TEXT    NOT NULL DEFAULT 'plain',
    media_source         TEXT    NOT NULL DEFAULT 'auto',
    print_scaling        TEXT    NOT NULL DEFAULT 'fit',
    req_print_scaling    TEXT    NOT NULL DEFAULT 'fit',
    page_range           TEXT    NOT NULL DEFAULT '',
    page_set             TEXT    NOT NULL DEFAULT 'all',
    req_page_set         TEXT    NOT NULL DEFAULT 'all',
    mirror               BOOLEAN NOT NULL DEFAULT false,
    watermark_text       TEXT    NOT NULL DEFAULT '',
    number_up            BIGINT  NOT NULL DEFAULT 1,
    number_up_layout     TEXT    NOT NULL DEFAULT 'lrtb',
    page_border          TEXT    NOT NULL DEFAULT 'none',

    unit_price_cents     BIGINT  NOT NULL DEFAULT 0,
    amount_cents         BIGINT  NOT NULL DEFAULT 0,
    refunded_cents       BIGINT  NOT NULL DEFAULT 0,
    pay_method           TEXT    NOT NULL DEFAULT '',

    -- pending_payment / held / paid / printing / printed / failed / refunded
    -- / expired / cancelled。取值定义在 orders.go 的状态常量里。
    -- held = 刷卡取件的待取件态：任务已转换好但【还没送 CUPS】。
    -- ⚠️ 它必须在 ListActiveOrderFiles 的保护名单里，否则 maintenance
    -- 会把员工还没取件的文件当过期文件删掉（orders.go 那条 SQL 是硬编码的）。
    status               TEXT    NOT NULL,
    -- ⚠️ 0 表示「没有支付单」，所以它【不能】建成外键（0 不存在于 payments）。
    payment_id           BIGINT  NOT NULL DEFAULT 0,
    job_id               TEXT    NOT NULL DEFAULT '',  -- 注意实际存的是 job URI，不是数字
    print_job_record_id  BIGINT  NOT NULL DEFAULT 0,
    error                TEXT    NOT NULL DEFAULT '',
    expires_at           TEXT    NOT NULL DEFAULT '',  -- '' = 未设置
    created_at           TEXT    NOT NULL,
    updated_at           TEXT    NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_print_orders_user_created
    ON print_orders(user_id, created_at DESC);
-- 补偿扫描：捞出卡在 paid / printing 的订单。
CREATE INDEX IF NOT EXISTS idx_print_orders_status_updated
    ON print_orders(status, updated_at);
-- 过期扫描。
CREATE INDEX IF NOT EXISTS idx_print_orders_status_expires
    ON print_orders(status, expires_at);
CREATE INDEX IF NOT EXISTS idx_print_orders_batch ON print_orders(batch_id);
-- 管理端全站列表 ORDER BY created_at DESC。
CREATE INDEX IF NOT EXISTS idx_print_orders_created ON print_orders(created_at DESC);

-- ── 支付单 ──────────────────────────────────────────────────────────
-- 一个支付单可覆盖同一批次的多个订单（靠 print_orders.payment_id 反向引用）。
-- 余额支付也写一行（provider='balance'，创建即 paid），两种方式的形状统一。
-- out_trade_no 唯一是幂等的第一层：渠道重复投递回调时靠它识别。
CREATE TABLE IF NOT EXISTS payments (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id        BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    purpose        TEXT   NOT NULL DEFAULT 'print',   -- print / topup
    provider       TEXT   NOT NULL,                   -- balance / alipay / mock
    out_trade_no   TEXT   NOT NULL,
    amount_cents   BIGINT NOT NULL,
    refunded_cents BIGINT NOT NULL DEFAULT 0,
    status         TEXT   NOT NULL,
    transaction_id TEXT   NOT NULL DEFAULT '',
    prepay_payload TEXT   NOT NULL DEFAULT '',
    raw_callback   TEXT   NOT NULL DEFAULT '',
    paid_at        TEXT   NOT NULL DEFAULT '',        -- '' = 未支付
    created_at     TEXT   NOT NULL,
    updated_at     TEXT   NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_payments_out_trade_no ON payments(out_trade_no);
CREATE INDEX IF NOT EXISTS idx_payments_user_created ON payments(user_id, created_at DESC);
-- 后台巡检：捞出未结算的在线支付单。
CREATE INDEX IF NOT EXISTS idx_payments_status ON payments(status);

-- ── 余额账本 ────────────────────────────────────────────────────────
-- 审计性质的表，只增不改。idempotency_key 唯一是「防重复入账」的最后一道闸。
CREATE TABLE IF NOT EXISTS wallet_transactions (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id             BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    kind                TEXT   NOT NULL,
    amount_cents        BIGINT NOT NULL,
    balance_after_cents BIGINT NOT NULL,
    order_id            BIGINT REFERENCES print_orders(id) ON DELETE SET NULL,
    payment_id          BIGINT REFERENCES payments(id)     ON DELETE SET NULL,
    idempotency_key     TEXT   NOT NULL,
    operator            TEXT   NOT NULL DEFAULT '',
    note                TEXT   NOT NULL DEFAULT '',
    created_at          TEXT   NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_wallet_transactions_idem
    ON wallet_transactions(idempotency_key);
CREATE INDEX IF NOT EXISTS idx_wallet_transactions_user_created
    ON wallet_transactions(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_wallet_transactions_order
    ON wallet_transactions(order_id);
-- 管理端全站流水 ORDER BY created_at DESC。
CREATE INDEX IF NOT EXISTS idx_wallet_transactions_created
    ON wallet_transactions(created_at DESC);

-- ── 管理操作审计 ────────────────────────────────────────────────────
-- 「谁在什么时候把什么从什么改成了什么」。
--
-- 为什么要单独一张表：余额调整已经有完整流水（wallet_transactions 里带
-- operator，注释里也写明它同时是一个审计动作），但【计费开关】和【价目表】
-- 改完什么都没留 —— 而「要不要收费」和「收多少」这两件事的变更历史，
-- 对一个收钱的系统来说不低于余额流水。只要不止一个人能进管理端，
-- 「谁把 A4 单价改成 0.02 的」这个问题一定会被问到。
--
-- ⚠️ 写入必须与业务改动在【同一个事务】里。分开写会得到两种都不能相信的
-- 状态：「改了但没记」和「记了但没改」。所以 store.InsertAudit 收 *sql.Tx
-- 而不是 *sql.DB —— 参数类型就是这条约定。反过来，审计写失败会连业务
-- 改动一起回滚，这是刻意的：宁可这次没改成，也不要一次没人认账的改动。
--
-- before_json / after_json 存【本次变更的字段】（不是整份快照）：系统设置
-- 几十个字段，而管理员真正要回答的是「这一次动了什么」。两条都为 '' 表示
-- 该动作没有「前后值」这个概念（如删除用户、立即清理）—— 那种动作的全部
-- 信息都在 summary 里。
CREATE TABLE IF NOT EXISTS admin_audit_log (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    actor       TEXT   NOT NULL,            -- 操作人用户名；会话解不出时 'unknown'
    action      TEXT   NOT NULL,            -- 动作键，取值见 internal/store/audit.go
    target      TEXT   NOT NULL DEFAULT '', -- 作用对象，如 'user#3' / '订单 #12' / '全局'
    summary     TEXT   NOT NULL DEFAULT '', -- 一句话，列表页直接显示它
    before_json TEXT   NOT NULL DEFAULT '',
    after_json  TEXT   NOT NULL DEFAULT '',
    created_at  TEXT   NOT NULL             -- RFC3339 UTC
);
-- 列表页按时间倒序翻页；两个索引分别服务「默认视图」与「只看某一类操作」。
CREATE INDEX IF NOT EXISTS idx_admin_audit_created
    ON admin_audit_log(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_admin_audit_action_created
    ON admin_audit_log(action, created_at DESC);

-- ── 设备异常事件 ────────────────────────────────────────────────────
-- 一台打印机的一类异常 = 一行。异常出现时开一行，消失时把 resolved_at 填上。
--
-- 为什么要落库而不是只发通知：
--   1. 「半夜卡纸」的真正代价不是没收到消息，而是【第二天才发现】。留着未恢复
--      的事件，管理端一进来就能看见「还有 1 台机器在卡纸」，而通知消息早就被
--      刷到聊天记录下面去了。
--   2. 通知是要【去重】的：巡检每分钟一轮，不落库就得在内存里维护一份
--      「这台机器这个毛病我已经说过了」，进程重启即丢 —— 重启后所有异常
--      重新叫一遍。落在行上的 notified_at 天然跨重启。
--   3. 事后要看「这台机器这个月卡了几次纸」，只有表能回答。
--
-- ⚠️ kind 是稳定的英文键（unreachable / paper_jam / out_of_paper …），取值见
-- internal/devicealert/health.go。中文文案在那一处映射，不进库 —— 与
-- admin_audit_log.action 同一条理由（中文在日志/URL/命令行里会被编码）。
--
-- detail 存【当时看到的原文】：printer-state-reasons 的原始串、或墨盒名 + 读数。
-- 排查时「media-empty-error」比「缺纸」有用得多，而这两者都要有 ——
-- 前者进 detail，后者进前端映射。
CREATE TABLE IF NOT EXISTS device_events (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    printer_uri TEXT   NOT NULL,            -- 队列 URI，与 CUPS_HOST 拼出来的那个
    kind        TEXT   NOT NULL,            -- 异常类别，见 devicealert.Kind*
    severity    TEXT   NOT NULL,            -- 'error' / 'warning'
    detail      TEXT   NOT NULL DEFAULT '',
    started_at  TEXT   NOT NULL,            -- 首次出现（RFC3339 UTC）
    updated_at  TEXT   NOT NULL,            -- 最后一次仍在（每轮巡检刷新）
    resolved_at TEXT   NOT NULL DEFAULT '', -- 空 = 还没恢复
    notified_at TEXT   NOT NULL DEFAULT ''  -- 最后一次发通知；'' = 还没发出去过
);
-- 「同一台打印机、同一类异常，同时只能有一条【未恢复】的记录」。
--
-- 这是部分唯一索引（WHERE resolved_at = ''），也是本表能被安全地每分钟 upsert
-- 一次的全部依据：巡检发现卡纸 → 插一行；下一轮还是卡纸 → 撞上这个唯一约束，
-- 走 ON CONFLICT 更新 updated_at，而不是再插一行。没有它，一次卡纸会在一天里
-- 攒出 1440 行，管理端列表全是同一件事。
--
-- ⚠️ 不能用普通唯一索引：那会让「上月卡纸」和「这月又卡了一次」撞车 ——
-- 历史记录必须能重复出现。
CREATE UNIQUE INDEX IF NOT EXISTS idx_device_events_open
    ON device_events(printer_uri, kind) WHERE resolved_at = '';
-- 管理端列表按时间倒序；横幅只查未恢复的那几条（走上面的部分索引）。
CREATE INDEX IF NOT EXISTS idx_device_events_started
    ON device_events(started_at DESC);

-- ── 设备告警静音 ────────────────────────────────────────────────────
-- 「这一台的这个毛病我知道，别再提醒我了」。
--
-- ── 为什么必须有这张表，而不是「点一下把事件关掉」就够 ──
--
-- 事件关掉之后，下一轮巡检（每 60 秒）会发现那个原因还在，于是重新开一条、
-- 重新发一次通知 —— 管理员点「已处理」的效果只维持一分钟。真正需要这个
-- 按钮的场景恰恰是【信号本身是错的】：比如某台 USB 打印机，cupsd 因为一次
-- 历史作业一直报着 media-empty，而纸盒里明明有纸。那种信号不会自己消失，
-- 关按钮就等于没关。
--
-- ── 静音怎么解除（这条是设计的关键） ──
--
-- 巡检发现【该类别已经不在异常列表里】时，删掉这条静音。也就是说：
-- 静音只对「当前这一次持续存在的毛病」有效，毛病一旦真的消失过、之后再犯，
-- 就是一次新问题，照常告警。这样静音不会变成「这台机器以后再也不告警了」。
CREATE TABLE IF NOT EXISTS device_alert_mutes (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    printer_uri TEXT NOT NULL,
    kind        TEXT NOT NULL,            -- 取值同 device_events.kind
    muted_at    TEXT NOT NULL,            -- RFC3339 UTC
    muted_by    TEXT NOT NULL DEFAULT ''  -- 操作人，进审计摘要用
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_device_alert_mutes_pair
    ON device_alert_mutes(printer_uri, kind);

