    ('save_history',         '1'),
    ('max_pages_per_job',    '0'),
    ('max_upload_bytes',     '0'),
    ('guest_mode',           '0'),
    ('billing_enabled',      '0'),
    ('order_ttl_minutes',    '15'),
    ('price_fallback_cents', '0'),
    ('payment_methods',      ''),
    ('site_base_url',        ''),
    -- 刷卡取件（拉式打印）。与 billing_enabled 互斥，见 admin_handlers.go。
    ('pull_mode_enabled',    '0'),
    ('pull_ttl_hours',       '72'),
    -- 设备异常告警。默认【关闭】：开之前要先配好 webhook 地址，
